DESIGNS=[]
def E(de,en,ode,oen):return dict(essentialUnderstandingDe=de,essentialUnderstandingEn=en,observablePerformanceDe=ode,observablePerformanceEn=oen)
def R(id,tde,ten,cde,cen,basis='written-explicit-task'):return dict(expectationId=id,taskClauseDe=tde,taskClauseEn=ten,criterionDe=cde,criterionEn=cen,creditBasis=basis)
def C(title,dde,den,rows,**kw):return dict(title=title,dataDe=dde,dataEn=den,taskRows=rows,modelAnswerDe='\n'.join(str(i+1)+'. '+r['criterionDe']for i,r in enumerate(rows)),modelAnswerEn='\n'.join(str(i+1)+'. '+r['criterionEn']for i,r in enumerate(rows)),**kw)
def D(prefix,archetype,expectations,axes,cases,atomicity,memory,boundary):DESIGNS.append(dict(prefix=prefix,archetype=archetype,expectations=expectations,axes=axes,cases=cases,atomicity=atomicity,memory=memory,boundary=boundary))
